variables.script:
/********************************************************************************
Variable Declaration
********************************************************************************/
var RegEx = [/[^A-Za-z]/, /[^A-Za-z0-9]/, /[^A-Za-z0-9\-]/, /[^A-Za-z0-9\.]/, /[^A-Za-z0-9\ ]/, /[^A-Za-z0-9\-\ ]/, /[^A-Za-z0-9\/ ]/, /[^A-Za-z ]/, /[^A-Za-z\- ]/, /[^A-Za-z\- \/]/, /[^A-Za-z\/ ]/, /[^0-1]/, /[^0-9]/, /[^0-9\.]/, /[^A-Za-z0-9\.\,\''\-\&amp;\ ]/, /[^0-9\/]/, /[^A-Za-z0-9\-, ]/, /[^A-Za-z\-\/\.\, ]/, /[^0-9NnAa\/]/, /[^0-6]/, /[^A-Za-z0-9\ \.\/]/];
var msgExitArray = new Array();
var msgChangeArray = new Array();

	msgExitArray[0] = "Enter a 5 digit ZIP Code.";		
	msgExitArray[1] = "Enter a 9 digit Social Security Number.";
	msgExitArray[2] = "Enter a 9 digit Alien Registration Number.";
	msgExitArray[3] = "Enter the 2 digit month, 2 digit day and 4 digit year in the format: mm/dd/yyyy.";
	msgExitArray[5] = "Enter only letters, numbers, space and hyphen.";
	msgExitArray[6] = "Enter a 12 character USCIS Online Account Number. Enter only numbers and letters.";	
	msgExitArray[7] = "Enter a 9 digit ITIN.";
	msgExitArray[8] = "Enter a 9 digit EIN.";
	msgExitArray[9] = "Enter an 11 character I-94 Arrival-Departure Record Number.";
	msgExitArray[10] = "Enter a six digit NAICS number.";
	msgExitArray[11] = "Enter the 2 digit month, 2 digit day and 4 digit year in the format: mm/dd/yyyy OR enter enter D/S for Duration of Status.";
	msgExitArray[12] = "Enter the 2 digit month, 2 digit day and 4 digit year in the format: mm/dd/yyyy OR if this date is the current date enter Present";
	msgExitArray[13] = "Enter the 13 digit Reciept Number."; 
	msgExitArray[14] = "Enter a 4 digit ZIP plus 4 extension.";

	msgChangeArray[0] = "Enter only letters.";
	msgChangeArray[1] = "Enter only letters, and numbers.";
	msgChangeArray[2] = "Enter only letters, numbers, and hyphens.";
	msgChangeArray[3] = "Enter only letters, numbers, and periods.";
	msgChangeArray[4] = "Enter only letters, numbers, and spaces.";
	msgChangeArray[5] = "Enter only letters, numbers, spaces, and hyphens.";
	msgChangeArray[6] = "Enter only letters, numbers, spaces, and slashes."; 
	msgChangeArray[7] = "Enter only letters, and spaces.";
	msgChangeArray[8] = "Enter only letters, spaces, and hyphens.";
	msgChangeArray[9] = "Enter only letters, spaces, and slashes.";
	msgChangeArray[10] = "Enter only letters, spaces, hyphens, and slashes.";
	msgChangeArray[11] = "Enter only numbers 0 or 1.";
	msgChangeArray[12] = "Enter only numbers.";
	msgChangeArray[13] = "Enter only numbers, and periods.";
	msgChangeArray[14] = "Enter only letters, numbers, period, comma, apostrophe, hyphen, ampersand and space.";
	msgChangeArray[15] = "Enter only numbers and slashes";
	msgChangeArray[16] = "Enter only letters, numbers, hyphens, spaces, and commas."
	msgChangeArray[17] = "Enter only letters, spaces, hyphens, slashes, periods and commas.";
	msgChangeArray[18] = "Enter numbers, slashes";
	msgChangeArray[19] = "Enter numbers 0 through 6 only";
	msgChangeArray[20] = "Enter letters, numbers, spaces, periods, and slashes";

/*******************************************************************************
This function monitors key strokes for fields to restrict entry to specific
characters
*******************************************************************************/

function valKeyEntry(regexValue, msgValue, msgType) 
{
	var regex = getRegEx(regexValue);	//Get the regular expression for the object keyboard entry.		
	var msgText = getMessage(msgValue, msgType); //Get the appropriate error message from the getMessage function	

	if(regex.test(xfa.event.change)) 
	{
  		xfa.event.change = "";
  		xfa.host.messageBox(msgText, "Field Validation Error", 0, 0);
	}
}

/********************************************************************************
Get the reg exp value. Return to the function
********************************************************************************/
function getRegEx(regexValue)
{
	var RegExValue;

	RegExValue = RegEx[regexValue];
	return RegExValue;	
}

/*******************************************************************************
This function creates the error messages for field validations.
When called the function returns the specified array value.
parameter msgValue - the array index value
var msgArray - Array of message values
var retMsg - The value in the array to be returned for display in error message
*******************************************************************************/
function getMessage(msgValue, msgType)
{
	var retMsg;

	if (msgType == "exit")
	{
	retMsg = msgExitArray[msgValue];	
	}
	else if (msgType == "change")
	{
	retMsg = msgChangeArray[msgValue];
	}
	return retMsg;	
}	


/*******************************************************************************
This function will validate the length or number of character entered.
Used for A- Number, US SSN, ZIP Code, etc.

*******************************************************************************/

function valLengthOnExit(objSOM, objValLen, msgValue, msgType)
{
	objSOM = xfa.resolveNode(objSOM);
	if (objSOM.rawValue == null || objSOM.rawValue == "")	//if the field is empty
	{
		// Do nothing
	}
	else
	{
		var msgText = getMessage(msgValue, msgType);	//Get the appropriate error message from the getMessage function	
		var objValueLen = objSOM.rawValue;			//convert the field value to an number. This eliminates any alpha characters entered
		objValueLen = objValueLen.length;	//convert back to a string and get the length of the string. This will indicate how many numbers were entered in the field

		if (objValueLen != objValLen)  //See if the entered value is equal in length to the total number of characters required by the field.
		{
		xfa.host.messageBox(msgText, "Validation Error", 0, 0); //post the error message, set the cursor back to the field and clear the entered field value. //msgValue = 
		objSOM.rawValue = "";
		xfa.host.setFocus(objSOM);				
		}						
	}
	//return msgValue;
}

/*******************************************************************************
This function will check that a valid date was entered 
*******************************************************************************/
function dtValidation(objSOM, dtFuture)
{
	objSOM= xfa.resolveNode(objSOM);
	var validDate;

	validDate = checkDate(objSOM);

	if (validDate == false)
	{
	xfa.host.messageBox("Date entered was not valid.\n\nThe Date must be a valid date, entered in the date format: MM/DD/YYYY\n\nRe-enter the Date", "Date Validation", 2, 0);
	xfa.host.setFocus(objSOM);
	}

	if (dtFuture == "1")
	{
		validDate = futureDate(objSOM);

		if (validDate == false)
		{
		xfa.host.messageBox("Date entered cannot be a future date\n\nRe-enter Date", "Future Date Validation", 2, 0);
		xfa.host.setFocus(objSOM);
		}
	}	
}


/***************************************************************
* Checks a date field for valid Date value
* @param - fldObject - date object to check
* @return - true (valid) or false (invalid)
****************************************************************/

function checkDate (objSOM)
{
	if (objSOM.rawValue != null && objSOM.rawValue != "")
	{
		var checkstr = "0123456789";
		var DateTemp = "";
		var blnError = false;
		var day;
		var month;
		var year;
		var leap = 0;
		var err = 0;		

		// To Retrieve display patter use:
		var strPattern = objSOM.format.picture.value;

		// Verify pattern is of form MM/DD/YYYY
		var arrPattern = strPattern.split("/");
		if (arrPattern.length != 3)
		return false;

		// Get date as formatted value
		var DateValue = objSOM.formattedValue;

		// Verify pattern is of form MM/DD/YYYY
		var arrDateVal = DateValue.split("/");

		if (arrDateVal.length != 3)
		return false;

		// Left-pad month and day if necessary
		for (i=0; i<arrDateVal.length; i++)
		{
			if (arrDateVal[i].length < 2)
			arrDateVal[1] = "0" + arrDateVal[i];
		}

		month = arrDateVal[0];
		day = arrDateVal[1];
		year = arrDateVal[2];

		//Retrieve raw value - it can be either one of the following formats
		switch (strPattern)
		{
			case "date{MM/DD/YYYY}":
			month = arrDateVal[0];
			day = arrDateVal[1];
			year = arrDateVal[2];
			break;

			case "date{MM/DD/YY}":
			month = arrDateVal[0];
			day = arrDateVal[1];			
				if (arrDateVal[2].length > 2)
				year = arrDateVal[2].sustr(2,2);
				else
				year = arrDateVal[2];
			break;

			case "date{YYYY-MM-DD}":
			month = arrDateVal[1];
			day = arrDateVal[2];
			year = arrDateVal[0];
			break;

			default:
			// Invalid format - return false
			blnError = true;
			return false;
			break;
		}

		// Basic validation
		if (year == 0)
		blnError = true;	

		if ((month < 1) || (month > 12))
		blnError = true;

		if (day < 1)
		blnError = true;

		if ((year % 4 == 0) || (year % 100 == 0) || (year % 400 == 0))
		leap = 1;

		if ((month == 2) && (leap == 1) && (day > 29))
		blnError = true;

		if ((month == 2) && (leap != 1) && (day > 28))
		blnError = true;			

		if ((day > 31) && ((month == "01") || (month == "03") || (month == "05") || (month == "07") || (month == "08") || (month == "10") || (month == "12")))
		blnError = true;

		if ((day > 30) && ((month == "04") || (month == "06") || (month == "09") || (month == "11")))
		blnError = true;

		if (blnError == false)
		{
			objSOM.rawValue = month + "/" + day + "/" + year;
			return true;
		}
		else
		{
			return false;
		}
	}
}

/****************************************************************
* Checks for a future date entered.
****************************************************************/
function futureDate(objSOM)
{
	if (objSOM.rawValue != null)
	{
		var today = new Date();
		var mm = String(today.getMonth() + 1);
		var dd = String(today.getDate());
		var yyyy = today.getFullYear();
		today = mm + "/" + dd + "/" + yyyy;

		var dateObject = util.scand("mm/dd/yyyy", objSOM.rawValue)
		var currentDate = util.scand("mm/dd/yyyy", today);

		if (dateObject > currentDate)
		{
		return false;
		}
	}	
}					


/****************************************************************
* test for valid state of time
****************************************************************/
function tmValidation(tmObj)
{
	tmObj = xfa.resolveNode(tmObj);

	var validTime = checkTime(tmObj);

	if (validTime == false)
	{
	xfa.host.messageBox("Time entered was not valid.\n\nThe Time must be a valid date, entered in the time in the 24 Hour format: HH:MM\n\nRe-enter the Time", "Time Validation", 2, 0);
	xfa.host.setFocus(dtObj);
	}
}

/*****************************************************************
* Checks a time field for valid Time value
* @param - fldObject - time object to check
* @return - true (valid) or false (invalid)
*****************************************************************/

function checkTime (fldObject, time)
{
	if (fldObject.rawValue != null && fldObject.rawValue != "")
	{
		// To Retrieve display patter use:
		var strPattern = fldObject.format.picture.value;	

		// Get date as formatted value
		var TimeValue = fldObject.formattedValue;	

		// Verify pattern is of form HH:MM
		var arrTimeVal = TimeValue.split(":");

		if (arrTimeVal.length != 2)
		return false;

		if (arrTimeVal[0] > 24)
		return false;

		if (arrTimeVal[1] > 59)
		return false;		
	}	
}

