// Functions to control fields or groups of fields.


function NumberFldCtrl(cbValue, cbSOM)
{
	//get the correct path statement for the object SOM
	var cbNode = xfa.resolveNode(cbSOM);
	// open the Number field
	cbNode.AptSteFlrNumber.access = "open";

	switch (cbValue)
	{
		case "APT":
		cbNode.CB_STE.rawValue = "";
		cbNode.CB_FLR.rawValue = "";
		break;

		case "STE": 
		cbNode.CB_APT.rawValue = "";
		cbNode.CB_FLR.rawValue = "";
		break;

		case "FLR": 
		cbNode.CB_STE.rawValue = "";
		cbNode.CB_APT.rawValue = "";
		break;

		default:
		cbNode.AptSteFlrNumber.rawValue = "";
		cbNode.AptSteFlrNumber.access = "readOnly";		
		break;
	}
}		

function stateCtrl(objSOM)
{
	var objNode = xfa.resolveNode(objSOM);

	if (objNode.State.rawValue != null && objNode.State.rawValue != " ")  
	{
		objNode.Province.access = "readOnly";
		objNode.PostalCode.access = "readOnly";
		objNode.Country.access = "readOnly";
		objNode.Country.rawValue = "USA";
	} 
	else if (objNode.State.rawValue == " ")
	{
		objNode.ZipCode.rawValue = "";
		objNode.Province.access = "open";
		objNode.PostalCode.access = "open";
		objNode.Country.access = "open";
		objNode.Country.rawValue = "";
	}
}	

function ProvPostalCtrl(objSOM)
{
	var objNode = xfa.resolveNode(objSOM)

	var provValue = objNode.Province.rawValue;
	var postValue = objNode.PostalCode.rawValue;

	if(provValue == null && postValue == null) 
	{
		objNode.State.access = 'open';
		objNode.ZipCode.access = 'open';    
	} 
	else 
	{
		objNode.State.access = 'readOnly';
		objNode.ZipCode.access = 'readOnly';
	}
}	

/*********************************************************************
This function will close and blank, or open all fields in a subform. 
*********************************************************************/

function sfAccessCtrl(sfSOM, sfAccess)
{
	sfSOM = xfa.resolveNode(sfSOM);
	var sfNodes = sfSOM.nodes;

	for (s=0; s<sfNodes.length; s++)
	{
		var item = sfNodes.item(s);

		if (item.className == "field")
		{
			if (sfAccess == "protected")
			{
			item.rawValue = null;
			item.access = sfAccess;
			}
			else
			{
			item.access = sfAccess;
			}
		}
	}
}

/*********************************************************************
* Works on checkboxes, turning them off and on.
*********************************************************************/

function cbController(cbSOM, cbToCheck)
{
	var CB = cbSOM + "." + cbToCheck + "[0]";

	CB = xfa.resolveNode(CB);
	CB.rawValue = "";
}	

function cbMultiController(cbSOM, cbToCheck, objIndex)
{
	var CB = cbSOM + "." + cbToCheck + "[" + objIndex + "]";

	CB = xfa.resolveNode(CB);
	CB.rawValue = "";
}
